content.query:
let iv = "{Interview}";
// The interview's voice sockets, found through the backend session span that names it.
let ws_ids = dependencies
  | where name == "voice.session" and tostring(customDimensions["voice.interview_id"]) == iv
  | distinct operation_ParentId;
let browser = dependencies
  | where isnotempty(iv) and client_Type == "Browser" and (name has iv or (type == "WebSocket" and trim_end(@"\.", id) in (ws_ids)))
  // The SDK stores a dependency id we set with a trailing "." (measured); the backend names it without.
  | project b_time = timestamp, call = tostring(split(name, "?")[0]), call_type = type, browser_ms = duration, b_id = trim_end(@"\.", id), operation_Id, result = resultCode;
let server = union requests, (dependencies | where name == "voice.session")
  | where client_Type != "Browser"
  | project s_id = id, s_parent = operation_ParentId, server_ms = duration;
let children = dependencies
  | where client_Type != "Browser" and not(name endswith " http send" or name endswith " http receive")
  | summarize ms = round(sum(duration)), n = count() by parent = operation_ParentId, name
  | summarize breakdown = make_bag(bag_pack(strcat(name, iff(n > 1, strcat(" x", tostring(n)), "")), ms)) by parent;
let azure_errors = traces
  | where message == "voice.azure_error"
  | summarize azure_errors = count(), avatar_rate_limited = countif(tostring(customDimensions.avatar_rate_limited) =~ "true") by parent = operation_ParentId;
browser
| join kind=leftouter server on $left.b_id == $right.s_parent
| join kind=leftouter children on $left.s_id == $right.parent
| join kind=leftouter azure_errors on $left.s_id == $right.parent
// A socket is open for the whole session on both sides: there is no network share to subtract.
| project b_time, call, call_type, result, browser_ms = round(browser_ms), server_ms = round(server_ms),
    network_ms = iff(call_type == "WebSocket", real(null), round(browser_ms - server_ms)), breakdown, azure_errors, avatar_rate_limited, operation_Id
| order by b_time asc
